```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name csvc, s.service_name ssvc, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms, approx_quantile(c.duration - s.duration,0.5)/1e6 gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='search' GROUP BY ALL ORDER BY n DESC",
          "claim": "search's client calls to rate take about 1,919 ms while rate's server spans stay near 0.8 ms; the gap is on the caller side."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY ALL",
          "claim": "Only search's rate.Rate/GetRates client calls are slow (p95 about 2,756 ms); its geo.Geo/Nearby calls stay at about 0.6 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, count(DISTINCT attr_k8s_pod_name) pods, sum(value) total FROM abnormal_metrics_sum WHERE service_name IN ('search','rate') AND metric IN ('k8s.pod.network.errors','k8s.pod.network.io') GROUP BY ALL ORDER BY 1,2",
          "claim": "search and rate pods show zero network errors and unchanged network I/O, so no transport-level loss or drops are visible."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, attr_k8s_pod_name pod, min(value) mn, max(value) mx FROM abnormal_metrics_sum WHERE metric='k8s.pod.uptime' AND service_name IN ('search','rate') GROUP BY ALL",
          "claim": "search and rate pods show monotonically increasing uptime during the incident, with no restarts or new pods."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name csvc, s.service_name ssvc, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95_ms, approx_quantile(s.duration,0.95)/1e6 server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='frontend' AND s.service_name='search' GROUP BY ALL",
          "claim": "frontend's search.Search/Nearby client spans have p95 near 2,950 ms, matching search's server time, so search's delay reaches frontend."
        }
      ]
    }
  ]
}
```

